+package com.example.contact;
+
+import java.io.Serializable;
+import java.util.ArrayList;
+import java.util.Collections;
+import java.util.List;
+
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.server.VaadinSession;
+
+/**
+ * Keeps the messages that have been sent, newest first.
+ * <p>
+ * The messages live in the Vaadin session, so they survive leaving the contact
+ * view and coming back to it, without being written anywhere on disk.
+ */
+public final class MessageStore implements Serializable {
+
+    private static final String ATTRIBUTE = MessageStore.class.getName();
+
+    private final List<ContactMessage> messages = new ArrayList<>();
+
+    private MessageStore() {
+    }
+
+    /**
+     * Returns the store of the current session, creating it on first use.
+     */
+    public static MessageStore current() {
+        VaadinSession session = VaadinSession.getCurrent();
+        if (session == null && UI.getCurrent() != null) {
+            session = UI.getCurrent().getSession();
+        }
+        if (session == null) {
+            // No session at hand (should not happen in a running UI); fall back
+            // to a throw-away store so that nothing blows up.
+            return new MessageStore();
+        }
+        MessageStore store = (MessageStore) session.getAttribute(ATTRIBUTE);
+        if (store == null) {
+            store = new MessageStore();
+            session.setAttribute(ATTRIBUTE, store);
+        }
+        return store;
+    }
+
+    /** Adds a message as the newest one. */
+    public void add(ContactMessage message) {
+        messages.add(0, message);
+    }
+
+    /** All messages sent so far, newest first. */
+    public List<ContactMessage> all() {
+        return Collections.unmodifiableList(new ArrayList<>(messages));
+    }
+}
